w = json.load(open("content/writing.json"))
ids = {x["id"] for x in w}
assert not (ids & {t["id"] for t in NEW}), "ID-Kollision"
w.extend(NEW)
json.dump(w, open("content/writing.json", "w"), ensure_ascii=False, indent=2)
from collections import Counter
print("total:", len(w), Counter(x["level"] for x in w), Counter(x["format"] for x in w))
for t in NEW:
    n = len(t["sample"].split())
    z = t["zielWort"]
    flag = "OK " if z * 0.85 <= n <= z * 1.45 else "LEN"
    print(flag, t["id"], t["level"], t["format"], f"sample {n}w ziel {z}")
